const fs = require("fs"), path = require("path"), os = require("os");
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "fgfs-"));
const out = [];
const log = (...a) => out.push(a.map((x) => (typeof x === "string" ? x : JSON.stringify(x))).join(" "));
const t = (name, fn) => { try { log(name, fn()); } catch (e) { log(name, "THROWS", e.code, e.syscall, String(e.message).split(dir).join("<dir>")); } };
const f = path.join(dir, "a.txt");
t("write/read", () => { fs.writeFileSync(f, "héllo"); return [fs.readFileSync(f, "utf8"), fs.readFileSync(f).length, fs.readFileSync(f, { encoding: "hex" })]; });
t("append", () => { fs.appendFileSync(f, " world"); return fs.readFileSync(f, "utf8"); });
t("stat", () => { const s = fs.statSync(f); return [s.size, s.isFile(), s.isDirectory(), s.mtime instanceof Date, typeof s.mtimeMs, (s.mode & 0o777).toString(8).length]; });
t("exists", () => [fs.existsSync(f), fs.existsSync(f + "x")]);
t("missing package.json", () => [fs.existsSync(path.join(dir, "package.json")), fs.statSync(path.join(dir, "package.json"), { throwIfNoEntry: false })]);
t("enoent", () => fs.readFileSync(path.join(dir, "nope")));
t("enoent stat", () => fs.statSync(path.join(dir, "nope")));
t("throwIfNoEntry", () => fs.statSync(path.join(dir, "nope"), { throwIfNoEntry: false }));
t("eisdir read", () => fs.readFileSync(dir));
t("mkdir", () => { fs.mkdirSync(path.join(dir, "x/y/z"), { recursive: true }); return fs.statSync(path.join(dir, "x/y/z")).isDirectory(); });
t("mkdir exists", () => fs.mkdirSync(path.join(dir, "x")));
t("mkdir recursive returns", () => fs.mkdirSync(path.join(dir, "p/q"), { recursive: true }).replace(dir, "<dir>"));
t("readdir", () => fs.readdirSync(dir));
t("readdir types", () => fs.readdirSync(dir, { withFileTypes: true }).map((d) => [d.name, d.isDirectory(), d.isFile()]));
t("readdir recursive", () => fs.readdirSync(dir, { recursive: true }));
t("rename", () => { fs.renameSync(f, path.join(dir, "b.txt")); return fs.existsSync(f); });
t("copy", () => { fs.copyFileSync(path.join(dir, "b.txt"), path.join(dir, "c.txt")); return fs.readFileSync(path.join(dir, "c.txt"), "utf8"); });
t("copy excl", () => fs.copyFileSync(path.join(dir, "b.txt"), path.join(dir, "c.txt"), fs.constants.COPYFILE_EXCL));
t("cp", () => { fs.cpSync(path.join(dir, "x"), path.join(dir, "x2"), { recursive: true }); return fs.readdirSync(path.join(dir, "x2")); });
t("fd", () => { const fd = fs.openSync(path.join(dir, "d.bin"), "w+"); fs.writeSync(fd, Buffer.from([1, 2, 3, 4, 5])); const b = Buffer.alloc(3); const n = fs.readSync(fd, b, 0, 3, 1); fs.closeSync(fd); return [n, [...b]]; });
t("truncate", () => { fs.truncateSync(path.join(dir, "d.bin"), 2); return fs.statSync(path.join(dir, "d.bin")).size; });
t("symlink", () => { fs.symlinkSync(path.join(dir, "b.txt"), path.join(dir, "ln")); return [fs.lstatSync(path.join(dir, "ln")).isSymbolicLink(), fs.readlinkSync(path.join(dir, "ln")).replace(dir, "<dir>"), fs.readFileSync(path.join(dir, "ln"), "utf8")]; });
t("link", () => { fs.writeFileSync(path.join(dir, "hl-src.txt"), "hardlink data"); fs.linkSync(path.join(dir, "hl-src.txt"), path.join(dir, "hl-link.txt")); return [fs.statSync(path.join(dir, "hl-src.txt")).nlink, fs.statSync(path.join(dir, "hl-link.txt")).nlink, fs.readFileSync(path.join(dir, "hl-link.txt"), "utf8")]; });
t("link write-through", () => { fs.writeFileSync(path.join(dir, "hl-link.txt"), "changed via link"); return fs.readFileSync(path.join(dir, "hl-src.txt"), "utf8"); });
t("link survives unlink", () => { fs.unlinkSync(path.join(dir, "hl-src.txt")); return [fs.existsSync(path.join(dir, "hl-src.txt")), fs.readFileSync(path.join(dir, "hl-link.txt"), "utf8"), fs.statSync(path.join(dir, "hl-link.txt")).nlink]; });
t("link eexist", () => fs.linkSync(path.join(dir, "hl-link.txt"), path.join(dir, "c.txt")));
t("link enoent", () => fs.linkSync(path.join(dir, "hl-nope.txt"), path.join(dir, "hl-target.txt")));
t("realpath", () => fs.realpathSync(path.join(dir, "x/../b.txt")).replace(fs.realpathSync(dir), "<dir>"));
t("unlink dir", () => fs.unlinkSync(path.join(dir, "x")));
t("rmdir nonempty", () => fs.rmdirSync(path.join(dir, "x")));
t("rm nonrecursive", () => fs.rmSync(path.join(dir, "x")));
t("rm force", () => fs.rmSync(path.join(dir, "nope"), { force: true }));
t("chmod", () => { fs.chmodSync(path.join(dir, "b.txt"), 0o600); return (fs.statSync(path.join(dir, "b.txt")).mode & 0o777).toString(8); });
t("access", () => { fs.accessSync(path.join(dir, "b.txt")); return fs.accessSync(path.join(dir, "nope")); });
t("write buffer", () => { fs.writeFileSync(path.join(dir, "e"), Buffer.from("buf")); return fs.readFileSync(path.join(dir, "e"), "latin1"); });
t("flags wx", () => fs.writeFileSync(path.join(dir, "e"), "x", { flag: "wx" }));
(async () => {
  await fs.promises.writeFile(path.join(dir, "p.txt"), "promise");
  log("promises", await fs.promises.readFile(path.join(dir, "p.txt"), "utf8"), (await fs.promises.stat(path.join(dir, "p.txt"))).size);
  try { await fs.promises.readFile(path.join(dir, "zzz")); } catch (e) { log("promise enoent", e.code); }
  const fh = await fs.promises.open(path.join(dir, "p.txt"), "r"); const { bytesRead, buffer } = await fh.read(Buffer.alloc(4), 0, 4, 0); await fh.close(); log("filehandle", bytesRead, buffer.toString());
  await new Promise((resolve) => fs.readFile(path.join(dir, "p.txt"), "utf8", (err, data) => { log("callback", err, data); resolve(); }));
  const ws = fs.createWriteStream(path.join(dir, "s.txt"));
  ws.write("line1\n"); ws.write("line2\n"); ws.end("line3\n");
  await new Promise((resolve) => ws.on("finish", resolve));
  const chunks = []; const rs = fs.createReadStream(path.join(dir, "s.txt"), { encoding: "utf8", highWaterMark: 8 });
  for await (const c of rs) chunks.push(c);
  log("streams", chunks.join("").length, chunks.length > 1);
  const partial = []; for await (const c of fs.createReadStream(path.join(dir, "s.txt"), { start: 2, end: 6 })) partial.push(c.toString()); log("range stream", partial.join(""));
  await new Promise((resolve) => require("stream").pipeline(fs.createReadStream(path.join(dir, "s.txt")), fs.createWriteStream(path.join(dir, "s2.txt")), (err) => { log("pipeline copy", err, fs.readFileSync(path.join(dir, "s2.txt"), "utf8").length); resolve(); }));
  fs.rmSync(dir, { recursive: true, force: true }); log("cleanup", fs.existsSync(dir));
  console.log(out.join("\n"));
})();
